// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        vm.assume(newOwner != address(this));
        vm.assume(newOwner != address(c));
        address originalOwner = c.owner();
        vm.prank(originalOwner);
        bool success;
        try c.setOwner(newOwner) returns (bool s) {
            success = s;
        } catch {
            success = false;
        }
        assertTrue(success);
    }
}
